sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var folderType = ("" + request.queryParams.type + "" || '')
            .toLowerCase()
            .replace(/\s/g, '');

        var folderId = request.queryParams.folderId;

        gs.info('Folder type: ' + folderType);
        gs.info('Folder ID: ' + folderId);

        var userId = gs.getUserID();
        var gr = new GlideRecord('x_1955226_connecto_folder');
        gr.addActiveQuery();

        // 🔥 1. If folderId is provided → ignore type and filter by ID
        if (folderId) {
            gr.addQuery('parent_folder_id', folderId);

        // 🔹 2. Otherwise apply type filters
        } else if (folderType === 'createdbymefolders') {
            gr.addQuery('owner', userId);

        } else if (folderType === 'sharedwithmefolders') {
            gr.addQuery('shared_with', 'CONTAINS', userId);

        } else if (folderType === 'publicfolders') {
            gr.addQuery('is_public', true);

        } else {
            gs.info('No filter applied, returning all folders');
        }

        gs.info('Encoded query: ' + gr.getEncodedQuery());

        gr.query();

        var folders = [];
        while (gr.next()) {
            folders.push({
                sys_id: gr.getValue('sys_id'),
                name: gr.getValue('name'),
                parent_folder_id: gr.getValue('parent_folder_id'),
                uniqueid: gr.getValue('uniqueid'),
                owner: gr.getValue('owner'),
                shared_with: gr.getValue('shared_with'),
                is_public: gr.getValue('is_public') === 'true',
				createdDate: gr.getValue('sys_created_on'),
				description: gr.getValue('description')
            });
        }

        response.setStatus(200);
        response.setBody({ success: true, folders });

    } catch (err) {
        response.setStatus(500);
        response.setBody({ success: false, message: err.message });
    }
})(request, response);
